-- Execute together with training_focus_v735.sql inside BEGIN / ROLLBACK.
CREATE TEMP TABLE tt_focus_tests(name text,passed boolean);
GRANT SELECT,INSERT ON tt_focus_tests TO authenticated;
CREATE FUNCTION pg_temp.reject_focus(statement text) RETURNS boolean LANGUAGE plpgsql AS $$ BEGIN BEGIN EXECUTE statement;EXCEPTION WHEN OTHERS THEN RETURN true;END;RAISE EXCEPTION 'Expected rejection: %',statement;END $$;
SELECT set_config('request.jwt.claims',jsonb_build_object('sub',(SELECT id FROM auth.users LIMIT 1),'role','authenticated')::text,true);
SET LOCAL ROLE authenticated;
SELECT set_config('tt_focus.previous',coalesce((SELECT id::text FROM public.training_goals_v7 WHERE owner_id=auth.uid() AND status='active'),''),true);
SELECT set_config('tt_focus.id',gen_random_uuid()::text,true);
SELECT public.set_training_focus_v735(current_setting('tt_focus.id')::uuid,'Wenn der Trigger fehlt, dann warte ich.',nullif(current_setting('tt_focus.previous'),'')::uuid);
INSERT INTO tt_focus_tests SELECT 'one_active_focus',count(*)=1 FROM public.training_goals_v7 WHERE owner_id=auth.uid() AND status='active';
INSERT INTO tt_focus_tests SELECT 'concurrent_direct_insert_blocked',pg_temp.reject_focus('insert into public.training_goals_v7(goal) values(''Wenn FOMO entsteht, dann pausiere ich.'')');
WITH s AS(INSERT INTO public.trading_sessions(session_date,status) VALUES('2099-03-01','open') RETURNING id) SELECT set_config('tt_focus.session',id::text,true) FROM s;
WITH a AS(INSERT INTO public.trading_accounts(account_name,account_type,default_instrument,default_quantity) VALUES('TEMP_FOCUS_TEST','demo','MNQ',1) RETURNING id) SELECT set_config('tt_focus.account',id::text,true) FROM a;
SELECT set_config('tt_focus.trade',public.record_trade_attempt_v735(current_setting('tt_focus.session')::uuid,'TEST','MNQ','long',jsonb_build_array(jsonb_build_object('account_id',current_setting('tt_focus.account'),'role','leader','instrument','MNQ','planned_quantity',1,'initial_sl_ticks',40)),'plan',gen_random_uuid(),'Geprüfte Testausnahme')::text,true);
INSERT INTO tt_focus_tests SELECT 'entry_captures_rule',observations->'training_focus'->>'goal_id'=current_setting('tt_focus.id') AND observations->'training_focus'->>'rule'='Wenn der Trigger fehlt, dann warte ich.' FROM public.trades WHERE id=current_setting('tt_focus.trade')::uuid;
UPDATE public.training_goals_v7 SET goal='Wenn der Trigger fehlt, dann bleibe ich draußen.' WHERE id=current_setting('tt_focus.id')::uuid;
INSERT INTO tt_focus_tests SELECT 'later_edit_keeps_entry_rule',observations->'training_focus'->>'rule'='Wenn der Trigger fehlt, dann warte ich.' FROM public.trades WHERE id=current_setting('tt_focus.trade')::uuid;
INSERT INTO tt_focus_tests SELECT 'snapshot_tampering_rejected',pg_temp.reject_focus(format('update public.trades set observations=observations-''training_focus'' where id=%L',current_setting('tt_focus.trade')));
INSERT INTO tt_focus_tests SELECT 'live_assessment_rejected',pg_temp.reject_focus(format('update public.trades set observations=observations||jsonb_build_object(''training_practice'',jsonb_build_object(''goal_id'',%L,''result'',''followed'')) where id=%L',current_setting('tt_focus.id'),current_setting('tt_focus.trade')));
SELECT public.close_trade_with_emotions_v7(current_setting('tt_focus.trade')::uuid,'TP',(SELECT jsonb_agg(jsonb_build_object('allocation_id',id,'realized_pnl_usd',10,'fees_usd',1)) FROM public.trade_account_allocations WHERE trade_id=current_setting('tt_focus.trade')::uuid),ARRAY['disciplined']);
UPDATE public.trades SET observations=observations||jsonb_build_object('training_practice',jsonb_build_object('goal_id',current_setting('tt_focus.id'),'result','followed','note','Trigger abgewartet'),'compliance_reviewed',true,'exception_reviews',jsonb_build_object('daily-limit','accepted'),'review_errors',jsonb_build_array(jsonb_build_object('id','focus-error','type','poor_entry','countermeasure','Wenn ein Trigger fehlt, dann bleibe ich draußen.','confirmed_breach',false))),rule_deviation=false WHERE id=current_setting('tt_focus.trade')::uuid;
INSERT INTO tt_focus_tests SELECT 'practice_saved_after_exit',observations->'training_practice'->>'result'='followed' FROM public.trades WHERE id=current_setting('tt_focus.trade')::uuid;
INSERT INTO tt_focus_tests SELECT 'wrong_goal_assessment_rejected',pg_temp.reject_focus(format('update public.trades set observations=jsonb_set(observations,''{training_practice,goal_id}'',to_jsonb(''wrong''::text)) where id=%L',current_setting('tt_focus.trade')));
SELECT set_config('tt_focus.next',gen_random_uuid()::text,true);
SELECT public.set_training_focus_v735(current_setting('tt_focus.next')::uuid,'Wenn ein Trigger fehlt, dann bleibe ich draußen.',current_setting('tt_focus.id')::uuid,current_setting('tt_focus.trade')::uuid,'focus-error');
INSERT INTO tt_focus_tests SELECT 'review_source_linked',source_trade_id=current_setting('tt_focus.trade')::uuid AND source_error_id='focus-error' AND error_type='poor_entry' FROM public.training_goals_v7 WHERE id=current_setting('tt_focus.next')::uuid;
INSERT INTO tt_focus_tests SELECT 'old_focus_preserved_as_replaced',status='replaced' FROM public.training_goals_v7 WHERE id=current_setting('tt_focus.id')::uuid;
INSERT INTO tt_focus_tests SELECT 'retry_idempotent',(public.set_training_focus_v735(current_setting('tt_focus.next')::uuid,'Wenn ein Trigger fehlt, dann bleibe ich draußen.',current_setting('tt_focus.id')::uuid,current_setting('tt_focus.trade')::uuid,'focus-error')).id=current_setting('tt_focus.next')::uuid;
INSERT INTO tt_focus_tests SELECT 'replaced_request_retry_rejected',pg_temp.reject_focus(format('select public.set_training_focus_v735(%L,''Wenn der Trigger fehlt, dann bleibe ich draußen.'')',current_setting('tt_focus.id')));
INSERT INTO tt_focus_tests SELECT 'stale_focus_rejected',pg_temp.reject_focus(format('select public.set_training_focus_v735(gen_random_uuid(),''Wenn FOMO entsteht, dann warte ich.'',%L)',current_setting('tt_focus.id')));
SELECT set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000099","role":"authenticated"}',true);
INSERT INTO tt_focus_tests SELECT 'foreign_source_rejected',pg_temp.reject_focus(format('select public.set_training_focus_v735(gen_random_uuid(),''Wenn ein Trigger fehlt, dann bleibe ich draußen.'',null,%L,''focus-error'')',current_setting('tt_focus.trade')));
RESET ROLE;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM tt_focus_tests WHERE passed IS NOT TRUE) THEN RAISE EXCEPTION 'Training focus tests failed';END IF;END $$;
SELECT jsonb_agg(to_jsonb(t)) AS training_focus_checks FROM tt_focus_tests t;
